L26_1 = {}
L26_1.m_CutScenKey_Talk = "SWANSONG_ACT3_INTERLUDE9@26#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 6800313
L26_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE9"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "MARYJANE_SWANSONG_NPC_NULL"
L26_1.m_Pos = "C"
L26_1.m_Talk_KOREA = "그렇네. 네가 여기 있다는 건, 모든 게 정해진 <color=#ffd34c>각본</color>이라는 거겠지."
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "そうね。あなたがここにいるってことは、すべてが決められた<color=#ffd34c>脚本</color>だったってことなのよね。"
L26_1.m_Talk_ENG = "Yes. And the reason you are here means that everything is according to the <color=#ffd34c>script</color>."
L26_1.m_Talk_TWN = "沒錯。你在這裡，表示一切都是按照<color=#ffd34c>劇本</color>進行的吧。"
L26_1.m_Talk_SCN = "没错。你在这里，意味着一切都是按照<color=#ffd34c>剧本</color>进行的吧。"
L26_1.m_Talk_DEU = "Yes. And the reason you are here means that everything is according to the <color=#ffd34c>script</color>."
L26_1.m_Talk_FRA = "Yes. And the reason you are here means that everything is according to the <color=#ffd34c>script</color>."
L27_1 = {}
L27_1.m_CutScenKey_Talk = "SWANSONG_ACT3_INTERLUDE9@27#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 6800313
L27_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE9"
L27_1.m_bWaitClick = true
