L27_1.m_CharStrID = "MARYJANE_SWANSONG_NPC_NULL"
L27_1.m_Pos = "C"
L27_1.m_Talk_KOREA = "실수였어. 역시 그날 모리어티의 계획대로, 극장에서 널 죽였어야 했는데."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "失敗したわ。やっぱりあの日、モリアーティの計画通り、劇場であなたを殺すべきだったのよ。"
L27_1.m_Talk_ENG = "It was a mistake. I should have killed you at the theater that day, just as Moriarty planned."
L27_1.m_Talk_TWN = "是我的失誤。果然那天應該按照莫里蒂的計畫，在劇院殺了你。"
L27_1.m_Talk_SCN = "是我的失误。果然那天应该按照莫里亚蒂的计划，在剧院杀了你。"
L27_1.m_Talk_DEU = "It was a mistake. I should have killed you at the theater that day, just as Moriarty planned."
L27_1.m_Talk_FRA = "It was a mistake. I should have killed you at the theater that day, just as Moriarty planned."
