L33_1.m_Face = "UNIT_PRIDE"
L33_1.m_CharStrID = "MARY_SWANSONG_NPC_SWAN"
L33_1.m_bFlip = true
L33_1.m_Pos = "L"
L33_1.m_Talk_KOREA = "후후, 상관없다니 그거 섭섭한 소리네."
L33_1.m_fTalkTime = 0.03
L33_1.m_Talk_JPN = "ふふ、関係ないだなんて悲しいこと言うね。"
L33_1.m_Talk_ENG = "Haha, you're upsetting me by saying that this has nothing to do with me."
L33_1.m_Talk_TWN = "呵呵，你說無所謂，那可真讓人傷心啊。"
L33_1.m_Talk_SCN = "呵呵，你说无所谓，那可真让人伤心啊。"
L33_1.m_Talk_DEU = "Haha, you're upsetting me by saying that this has nothing to do with me."
L33_1.m_Talk_FRA = "Haha, you're upsetting me by saying that this has nothing to do with me."
L34_1 = {}
