L34_1.m_bFlip = true
L34_1.m_Pos = "L"
L34_1.m_Talk_KOREA = "나는 네 전속 스태프이고, 너는 우리 극단을 대표하는 프리마돈나인걸?"
L34_1.m_fTalkTime = 0.03
L34_1.m_Talk_JPN = "私はあなたの専属スタッフで、あなたは我が劇団を代表するプリマドンナなのよ？"
L34_1.m_Talk_ENG = "I'm your personal staff, and you're the prima donna that represents our theater."
L34_1.m_Talk_TWN = "我是你的專屬助理，而你是我們劇團的首席女主角喔？"
L34_1.m_Talk_SCN = "我是你的专属助理，而你是我们剧团的首席女主角哦？"
L34_1.m_Talk_DEU = "I'm your personal staff, and you're the prima donna that represents our theater."
L34_1.m_Talk_FRA = "I'm your personal staff, and you're the prima donna that represents our theater."
