L44_1 = "그때 너는 나를 구해주었잖아! 앞으로도 포기하지 않고 무대에 서 달라면서?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "あの時、あなたは私を助けてくれた！　これからも諦めないで舞台に立ってほしいって励んでくれた！"
L43_1.m_Talk_JPN = L44_1
