L50_1 = "<color=#ffd34c>그대가 원하는 바를 해라. 그것이 곧 그대의 법이다.</color>"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "<color=#ffd34c>汝の欲することを為せ、それが汝の法とならん。</color>"
L49_1.m_Talk_JPN = L50_1
L50_1 = "<color=#ffd34c>Do what thou wilt. For it shall be thy law.</color>"
L49_1.m_Talk_ENG = L50_1
L50_1 = "<color=#ffd34c>行汝欲行之事，此為律法之全部。</color>"
