L51_1 = "나에게도 원하는 게 있어. 그걸 방해한다면 너라도 용서하지 않을 거야."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "私にも叶えたいことがある。それを邪魔するなら、いくらあなたでも許さない。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "I also want something. And if you interfere, I won't forgive anyone. Even you."
L50_1.m_Talk_ENG = L51_1
L51_1 = "我也有我想要的東西。如果有人阻礙，就算那是你，我也不會原諒。"
L50_1.m_Talk_TWN = L51_1
