L39_1 = "그 말은 의식을 수행할 장소가 정해져 있고, 그간 회수한 증표가 거기 있다는 소리야."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "それはつまり、儀式を行う場所が他にあって、今まで回収してきた印がそこにあるということだ。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "That means that the location to perform the ritual is set, and all the marks will also be there."
L38_1.m_Talk_ENG = L39_1
L39_1 = "這表示儀式的執行地點是確定的，連同之前回收的標記也在那裡。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "这意味着仪式的执行地点是确定的，连同之前回收的标记也在那里。"
