L7_1.m_CharScale = L8_1
L7_1.m_CharScaleTime = 0.01
L8_1 = "내가 범인의 정체를 확신하게 된 건, 세 번째 현장에서 거울 조각을 발견했을 때였어."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "私が犯人の正体を確信したのは、三番目の現場で鏡の破片を見つけた時だった。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "I was convinced I knew who the culprit was when we found the mirror fragment at the third murder scene."
L7_1.m_Talk_ENG = L8_1
L8_1 = "我確定兇手的身份，是在第三案發現場看到鏡子碎片的時候。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "我确信凶手的身份，是在第三案发现场看到镜子碎片的时候。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "I was convinced I knew who the culprit was when we found the mirror fragment at the third murder scene."
L7_1.m_Talk_DEU = L8_1
L8_1 = "I was convinced I knew who the culprit was when we found the mirror fragment at the third murder scene."
L7_1.m_Talk_FRA = L8_1
