L8_1.m_CharScale = L9_1
L8_1.m_CharScaleTime = 0.01
L9_1 = "거울이라는 마도구에 접근할 수 있는 사람은 극장 관계자뿐이었으니까."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "鏡という魔道具に接近できる人物は劇場の関係者だけだったからな。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "The only ones who could have had access to the mirror Curio would be the theater staff."
L8_1.m_Talk_ENG = L9_1
L9_1 = "能夠接觸到鏡子魔導具的只有劇院相關的人員。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "能够接触到镜子魔导具的只有剧院相关的人员。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "The only ones who could have had access to the mirror Curio would be the theater staff."
L8_1.m_Talk_DEU = L9_1
L9_1 = "The only ones who could have had access to the mirror Curio would be the theater staff."
