L9_1.m_CharScale = L10_1
L9_1.m_CharScaleTime = 0.01
L10_1 = "하지만 거울을 가지고 있는 이상, 지금처럼 현행범으로 잡지 않으면 의미가 없었지."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "だが鏡を持っている以上、今みたいに現行犯で捕まえないと意味がなかったんだ。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "But because of the mirror, it was meaningless to catch the killer red-handed."
L9_1.m_Talk_ENG = L10_1
L10_1 = "因為有那面鏡子在，不當場抓住現行犯是沒有任何意義的。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "因为有那面镜子在，不当场抓住现行犯是没有任何意义的。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "But because of the mirror, it was meaningless to catch the killer red-handed."
L9_1.m_Talk_DEU = L10_1
