L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "L"
L19_1 = "아마도 사건을 알게 된 모리어티 교수가 흥미를 느끼고 심야의 살인마를 거두었겠지."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "そして、おそらく事件について知ったモリアーティ教授が興味を持ち、深夜の殺人鬼を匿ったのだろう。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Professor Moriarty must have taken the Midnight Killer under his wing after hearing about that incident."
L18_1.m_Talk_ENG = L19_1
L19_1 = "也許是莫里蒂教授找上了她，因為興趣收留了午夜殺人魔吧。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "也许是莫里亚蒂教授找上了她，因为兴趣收留了午夜杀人魔吧。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Professor Moriarty must have taken the Midnight Killer under his wing after hearing about that incident."
L18_1.m_Talk_DEU = L19_1
