L6_1 = "ABBERLINE_SWANSONG_NPC_NULL"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "C"
L6_1 = "흉기는 발견되지 않았지만, 심야의 살인마의 수법은 날카로운 금속 날붙이에 의한 척살."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "凶器は発見されてないが、深夜の殺人鬼の手口は鋭い刃物による刺殺。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "The murder weapon was never found, but the Midnight Killer's M.O. was using a sharp metal blade."
L5_1.m_Talk_ENG = L6_1
L6_1 = "雖然沒有發現兇器，但午夜殺人魔的手法是用鋒利的金屬刀具進行刺殺。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "虽然没有发现凶器，但午夜杀人魔的手法是用锋利的金属刀具进行刺杀。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "The murder weapon was never found, but the Midnight Killer's M.O. was using a sharp metal blade."
L5_1.m_Talk_DEU = L6_1
L6_1 = "The murder weapon was never found, but the Midnight Killer's M.O. was using a sharp metal blade."
L5_1.m_Talk_FRA = L6_1
