L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C"
L7_1 = "하지만 그 흉터는 크기와 모양이 일정하지 않고 모두 제각각이었지."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "だがその傷跡は一定の大きさや形ではなく、みんなバラバラだった。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "However, the scars' size and shape were all different."
L6_1.m_Talk_ENG = L7_1
L7_1 = "受害者身上的那些傷痕大小和形狀都不一致。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "受害者身上的那些伤痕大小和形状都不一致。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "However, the scars' size and shape were all different."
L6_1.m_Talk_DEU = L7_1
L7_1 = "However, the scars' size and shape were all different."
L6_1.m_Talk_FRA = L7_1
