L8_1 = "In other words, it wasn't a blade with a certain shape."
L7_1.m_Talk_ENG = L8_1
L8_1 = "也就是說，作案刀具並沒有固定的形態。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "也就是说，作案刀具并没有固定的形态。"
