L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "C"
L21_1 = "그 여자의 증표를 노릴 지 알고 있었다는 건, 다시 말해 메시지를 파악했다는 뜻이겠지."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "あの女の印を狙うと知っていたということは、つまりメッセージを把握したということだろう。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Seeing how you know, I was after that girl's mark can only mean that you figured out what the messages meant."
L20_1.m_Talk_ENG = L21_1
L21_1 = "知道她會被盯上，是因為你已經充分理解了塗鴉的資訊。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "知道她会被盯上，是因为你已经充分理解了涂鸦的信息。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Seeing how you know, I was after that girl's mark can only mean that you figured out what the messages meant."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Seeing how you know, I was after that girl's mark can only mean that you figured out what the messages meant."
