L24_1 = "For the ritual to succeed, you needed the power manifested by the collective unconsciousness."
L23_1.m_Talk_ENG = L24_1
L24_1 = "為了順利完成儀式，必定需要從集體無意識中汲取力量。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "为了顺利完成仪式，必定需要从集体无意识中汲取力量。"
