L49_1 = 198
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 6800313
L48_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE9"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_Face = "UNIT_LAUGH"
L49_1 = "ABBERLINE_SWANSONG_NPC_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "L"
L49_1 = "옛 현인들은 이 세상이 만들어진 원리를 알아내기 위해 수많은 시도와 노력을 해왔지."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "古くから知識人たちは、この世界が作られた原理を解明するために、たくさんの試みと努力をしてきた。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "The sages of old made numerous attempts to find out the principles of how this world was created."
L48_1.m_Talk_ENG = L49_1
L49_1 = "古代賢者們為了揭示這個世界的構造原理，進行了無數次嘗試和努力。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "古代贤者们为了揭示这个世界的构造原理，进行了无数次尝试和努力。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "The sages of old made numerous attempts to find out the principles of how this world was created."
L48_1.m_Talk_DEU = L49_1
L49_1 = "The sages of old made numerous attempts to find out the principles of how this world was created."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "SWANSONG_ACT3_INTERLUDE9@199#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 199
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 6800313
L49_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE9"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "ABBERLINE_SWANSONG_NPC_NULL"
L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "L"
L50_1 = "이 세상의 모든 것과 연결된, 그 보이지 않는 실을 규명해내기 위해서."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "この世界のすべてと繋がった、その見えない糸を明らかにするために。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "To uncover the invisible thread that connects everything in this world."
L49_1.m_Talk_ENG = L50_1
L50_1 = "為了探明與這個世界萬物相連的那條無形之線。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "为了探明与这个世界万物相连的那条无形之线。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "To uncover the invisible thread that connects everything in this world."
L49_1.m_Talk_DEU = L50_1
L50_1 = "To uncover the invisible thread that connects everything in this world."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "SWANSONG_ACT3_INTERLUDE9@200#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 200
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 6800313
L50_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE9"
