L51_1 = "ABBERLINE_SWANSONG_NPC_NULL"
L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "L"
L51_1 = "연금술 역시 마찬가지야. 표면적으로는 쓸모 없는 금속을 금으로 바꾸는 기술이었지만."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "錬金術もまた同じだ。表面的には使えない金属を金に変える技術だったのだが、"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Alchemy is the same. It was a technique to transform useless metal into gold on the surface."
L50_1.m_Talk_ENG = L51_1
L51_1 = "煉金術也是一樣的。雖然表面上看是將無用的金屬變成金子的技術。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "炼金术也是一样的。虽然表面上看是将无用的金属炼成金子的技术。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Alchemy is the same. It was a technique to transform useless metal into gold on the surface."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Alchemy is the same. It was a technique to transform useless metal into gold on the surface."
L50_1.m_Talk_FRA = L51_1
