L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "L"
L2_1 = "그 내면에는 인간의 영혼을 불멸하게……."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "その裏には、人間の魂を不滅にする……"
L1_1.m_Talk_JPN = L2_1
L2_1 = "However, the real goal was for the human soul to become immortal..."
L1_1.m_Talk_ENG = L2_1
L2_1 = "但真正的目的是將人類的靈魂變為不朽……"
L1_1.m_Talk_TWN = L2_1
