L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "L"
L3_1 = "다시 말해, 신적 존재로 탈바꿈하는 기술을 뜻하기도 하지."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "つまり、神的存在に変える技術を意味したりもする。"
