L3_1 = "Simply put, it meant a technique to transform into a divine being."
L2_1.m_Talk_ENG = L3_1
L3_1 = "換句話說，這是一項意指變為神之存在的技術。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "换句话说，这是一项意指变为神之存在的技术。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Simply put, it meant a technique to transform into a divine being."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Simply put, it meant a technique to transform into a divine being."
