L5_1.m_Talk_ENG = L6_1
L6_1 = "讓她經歷第一之裁判吧。來到我面前，她將如<color=#ffd34c>銀</color>一般純淨。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "让她经历第一之裁判吧。来到我面前，她将如<color=#ffd34c>银</color>一般纯净。"
