L11_1 = "그렇지 않나, 심야의 살인마?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "違うか？　深夜の殺人鬼。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Isn't that right, Midnight Killer?"
