L27_1 = "점성술에서는 육안으로 관측할 수 있는 일곱 개의 천체를 중요하게 생각한다네."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "占星術では肉眼で観測できる7つの天体を重要視している。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Astrology emphasized the seven celestial bodies that couldn't be observed by the naked eye."
L26_1.m_Talk_ENG = L27_1
L27_1 = "在古典占星術中，人們極其重視肉眼可見的七大天體。"
