L28_1 = "이를 테면, 하늘이라는 무대에서 각각의 천체는 등장인물과 같지."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "空という舞台において、それぞれの天体はいわば登場人物に等しい。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "For instance, if the sky is the stage, each celestial body is like a character."
L27_1.m_Talk_ENG = L28_1
L28_1 = "比如說，在天空這個舞台上，每個天體就像是登場的人物。"
