L40_1 = "그 금속은 각각 납, 주석, 철, 금, 황동, 수은 그리고 은이라네."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "その金属とはすなわち、鉛、錫、鉄、金、黄銅、水銀、そして銀だ。"
