L42_1 = "또한 점성술에서는 인체를 하나의 축소된 소우주라고 보기도 해."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "また、占星術では人体を一つの縮小された小宇宙だとも見ている。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Also, astrology sees the human body as a miniature microcosm."
L41_1.m_Talk_ENG = L42_1
L42_1 = "此外，在占星術中，人的身體也被視為一個縮小的微型宇宙。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "此外，在占星术中，人的身体也被视为一个缩小的微型宇宙。"
