L50_1 = "게자리의 수호성은 <color=#ffd34c>달</color>. 달의 고유 금속은 <color=#ffd34c>은</color>이지."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "かに座の守護星は<color=#ffd34c>月</color>。月の固有金属は<color=#ffd34c>銀</color>だ。"
L49_1.m_Talk_JPN = L50_1
