L50_1 = "巨蟹座的守護星是<color=#ffd34c>月亮</color>。而月亮所代表的金屬是<color=#ffd34c>銀</color>。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "巨蟹座的守护星是<color=#ffd34c>月亮</color>。而月亮所代表的金属是<color=#ffd34c>银</color>。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Cancer's ruling celestial body is the <color=#ffd34c>moon</color>. And the moon's unique metal is <color=#ffd34c>silver</color>."
