L35_1 = "그 뒤에 일련의 살인이 의식으로 작용하기 시작한 건, 두 번째 살인부터였을 거야."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "その後に一連の殺人が儀式になり始めたのは、二番目の殺人からのはずだ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "After the second murder, the serial killings started to serve as the ritual."
L34_1.m_Talk_ENG = L35_1
L35_1 = "而之後的一系列伴隨著儀式的連環謀殺，應該是從你第二次殺人開始。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "而之后的一系列伴随着仪式的连环谋杀，应该是从你第二次杀人开始。"
