L38_1.m_Talk_JPN = L39_1
L39_1 = "You're right. Three years ago, I had a calling after I lost her."
L38_1.m_Talk_ENG = L39_1
L39_1 = "沒錯。三年前失去那個孩子之後，我得到了某種啟示。"
L38_1.m_Talk_TWN = L39_1
