L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "C"
L40_1 = "매일 같이 잠들 기 전, 머릿속에 속삭임이 들려왔지."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "毎日眠りにつく前、何者かが私の脳裏に囁いてきたのさ。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Every night before going to sleep, I could hear a whisper in my head."
L39_1.m_Talk_ENG = L40_1
L40_1 = "每天入睡前，我的腦海中都會響起低語。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "每天入睡前，我的脑海中都会响起低语。"
