L41_1 = "ALEISTER_SWANSONG_NPC_QM"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "C"
L41_1 = "이 세계에 뿌려진 여섯 개의 증오스러운 증표를 바치면, 다시 만날 수 있을 거라고."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "この世界に振り撒かれた六つの憎い印を捧げれば、また会えるって。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "That I could meet her again if I offered the six dreaded marks scattered throughout this world."
L40_1.m_Talk_ENG = L41_1
L41_1 = "如果獻上散佈在這個世界上的六個憎恨之印，就能再次與 她相見了。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "如果献上散布在这个世界上的六个憎恨之印，就能再次与她相见了。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "That I could meet her again if I offered the six dreaded marks scattered throughout this world."
L40_1.m_Talk_DEU = L41_1
L41_1 = "That I could meet her again if I offered the six dreaded marks scattered throughout this world."
