L43_1 = "그래, 모리어티는 그게 천사라고 했어. 하지만 그게 무엇이든 중요하지 않아."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "ああ、モリアーティはそれが天使って言っていた。だけど、それが何なのかは重要じゃない。"
