L44_1 = "이 썩어빠진 세상을 부수고, 다시 창조해낼 힘을 가지고 있다면 나에겐 그게 천사니까."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "この腐った世界を壊して、作り直す力を持っているなら。私にとってはそれこそが天使だから。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "For anything that has the power to burn down this retched world and recreated it, it will be an angel to me."
L43_1.m_Talk_ENG = L44_1
L44_1 = "如果有任何力量可以摧毀這個腐朽的世界，並重新創造它，對我來說那個就是天使。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "如果有任何力量可以摧毁这个腐朽的世界，并重新创造它，对我来说那个就是天使。"
