L7_1.m_CharStrID = L8_1
L8_1 = "그 아이 외에는 누구도 나를 그 이름으로 불러주지 않았으니까."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "あの子を除いては、誰も私のことをその名前で呼んでくれなかったから。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Nobody but her would ever call me by that name."
