L9_1 = "그리고 그 아이와 다시 만나기 전까지는, 누구도 나를 그 이름으로 부르지 않길 바랬고."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "それに、あの子にまた会えるまでは、誰にもその名前で呼んでほしくなかった。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "And until I am reunited with her, I don't wish anyone to call me by that."
